LANGS = ['en', 'es', 'de', 'it', 'pt']
root = pathlib.Path(__file__).resolve().parent.parent / 'assets' / 'i18n'
for col, lang in enumerate(['fr'] + LANGS):
    p = root / f'{lang}.json'
    data = json.loads(p.read_text())
    added = 0
    for row in T:
        k = row[0]
        if k not in data:
            data[k] = row[col] if col else k
            added += 1
    p.write_text(json.dumps(data, ensure_ascii=False, indent=1, sort_keys=True) + '\n')
    print(lang, '+', added)
